/* CSA5111 Question 31: independent executable */
#include "common/crypto_common.h"
static void q31(void){puts("Rb constants for CMAC reduction: 64-bit block: 0x1B; 128-bit block: 0x87.");int bits=(int)readint("Block size (64=DES demo, 128=AES demo): ");unsigned char v[16]={0};if(bits==64){char h[128];readstr("DES key (16 hex digits): ",h,sizeof h);uint64_t key;if(strlen(h)!=16||!parse_u64(h,&key)){puts("Invalid DES key.");return;}uint64_t L=des_block(0,key,0);for(int i=0;i<8;i++)v[i]=(unsigned char)(L>>(56-8*i));}else if(bits==128){char h[128];readstr("AES-128 key (32 hex digits): ",h,sizeof h);unsigned char key[16],zero[16]={0};if(unhex(h,key,16)!=16){puts("Invalid AES key.");return;}aes_block(key,zero,v);}else{puts("Choose 64 or 128.");return;}int n=bits/8;printf("L = E_K(0^n) = ");printhex(v,n);int msb=v[0]>>7;for(int i=0;i<n;i++){int next=(i+1<n)?(v[i+1]>>7):0;v[i]=(unsigned char)((v[i]<<1)|next);}if(msb)v[n-1]^=(bits==64?0x1B:0x87);printf("K1 = ");printhex(v,n);msb=v[0]>>7;for(int i=0;i<n;i++){int next=i+1<n?(v[i+1]>>7):0;v[i]=(unsigned char)((v[i]<<1)|next);}if(msb)v[n-1]^=(bits==64?0x1B:0x87);printf("K2 = ");printhex(v,n);puts("The conditional Rb XOR performs reduction modulo the CMAC block-size polynomial.");}
int main(void){ OSSL_PROVIDER_load(NULL,"default"); OSSL_PROVIDER_load(NULL,"legacy"); q31(); return 0; }
